    const { id } = req.params;
    try {
        const deleted = await Programme.removeById(id);
        if (!deleted) return res.status(404).json({ error: 'Programme not found' });
        res.status(204).send();
    } catch (err) {
        res.status(500).json({ error: err.message });
    }
}

module.exports = { list, create, update, remove };

